import socket, struct, threading

A, NS, SOA = 1, 2, 6
PUERTO = 5300

# ---------- formato del mensaje (el mismo de RFC 1035, sin compresión de nombres) ----------
def nombre_a_bytes(n):
    return b"".join(bytes([len(p)]) + p.encode() for p in n.rstrip(".").split(".") if p) + b"\0"

def bytes_a_nombre(m, i):
    partes, salto = [], None
    while m[i]:
        if m[i] >= 0xC0:                        # puntero de compresión
            salto = salto or i + 2
            i = ((m[i] & 0x3F) << 8) | m[i + 1]
            continue
        partes.append(m[i + 1:i + 1 + m[i]].decode()); i += 1 + m[i]
    return ".".join(partes) + ".", (salto or i + 1)

def rdata(tipo, v):
    if tipo == A: return socket.inet_aton(v)
    if tipo == NS: return nombre_a_bytes(v)
    mn, rn, *nums = v                          # SOA
    return nombre_a_bytes(mn) + nombre_a_bytes(rn) + struct.pack(">5I", *nums)

def armar(id_, flags, preg, *secciones):
    m = struct.pack(">6H", id_, flags, 1, *[len(s) for s in secciones]) + nombre_a_bytes(preg[0]) + struct.pack(">2H", preg[1], 1)
    for sec in secciones:
        for n, t, ttl, v in sec:
            d = rdata(t, v); m += nombre_a_bytes(n) + struct.pack(">HHIH", t, 1, ttl, len(d)) + d
    return m

def leer(m):
    id_, fl, qd, an, ns, ar = struct.unpack(">6H", m[:12]); n, i = bytes_a_nombre(m, 12); t = struct.unpack(">H", m[i:i + 2])[0]; i += 4
    secs = []
    for cuantos in (an, ns, ar):
        sec = []
        for _ in range(cuantos):
            nom, i = bytes_a_nombre(m, i); tp, _, ttl, ln = struct.unpack(">HHIH", m[i:i + 10]); i += 10
            if tp == A: v = socket.inet_ntoa(m[i:i + 4])
            elif tp == NS: v = bytes_a_nombre(m, i)[0]
            else: v = struct.unpack(">5I", m[bytes_a_nombre(m, bytes_a_nombre(m, i)[1])[1]:][:20])[4]   # SOA: devuelvo el campo «minimum»
            sec.append((nom, tp, ttl, v)); i += ln
        secs.append(sec)
    return id_, fl & 15, (n, t), *secs

# ---------- servidor autoritativo ----------
def responder(zona, origen, q):
    id_, _, (n, t) = q[:3]
    soa = [r for r in zona if r[1] == SOA]
    deleg = [r for r in zona if r[1] == NS and r[0] != origen and (n == r[0] or n.endswith("." + r[0]))]
    if deleg:                                   # no soy la autoridad de ese nombre: derivo (con «pegamento»)
        pegamento = [r for r in zona if r[1] == A and r[0] in {d[3] for d in deleg}]
        return armar(id_, 0x8000, (n, t), [], deleg, pegamento)
    resp = [r for r in zona if r[0] == n and r[1] == t]
    if resp: return armar(id_, 0x8400, (n, t), resp, [], [])               # AA=1
    existe = any(r[0] == n for r in zona)
    return armar(id_, 0x8400 | (0 if existe else 3), (n, t), [], soa, [])  # sin datos / NXDOMAIN

def servir(ip, zona, origen):
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.bind((ip, PUERTO))
    def bucle():
        while True:
            m, quien = s.recvfrom(512)
            s.sendto(responder(zona, origen, leer(m)), quien)
    threading.Thread(target=bucle, daemon=True).start()

